package org.racedaydreams.data
import android.test.AndroidTestCase
import org.racedaydreams.domain.recording.RunMetricsEngine
import org.racedaydreams.recording.GpxFiles
import java.io.*
import java.time.Instant

class RunRecordingStoreTest:AndroidTestCase(){
 override fun setUp(){super.setUp();ProfileDatabase.get(context).writableDatabase.apply{delete("recording_sessions",null,null);delete("activities",null,null)}}
 override fun tearDown(){newClear();super.tearDown()}
 private fun newClear(){SqliteUserPreferencesRepository(context).clear()}
 private fun trace(id:String="native"):RecordingStore.Session {val store=RecordingStore(context);val e=RunMetricsEngine(0,Instant.parse("2026-10-22T00:00:00Z"));for(i in 0..100)e.accept(RunMetricsEngine.Fix(Instant.parse("2026-10-22T00:00:00Z").plusSeconds(i.toLong()),i*1000L,0.0,i*0.00003,3.0,null,null,3.0));store.start(id,Instant.parse("2026-10-22T00:00:00Z"),0);store.flush(id,e.points(),e.events(),0,0,100000,"ACTIVE");return store.unfinished()!!}
 fun testFinalizationRetainsRawPointsAndComputesSamples(){val s=trace();val id=RecordingStore(context).finish(s,100000);val a=FeatureStore(context).activities().first{it.id()==id};assertEquals(101,a.samples().size);assertEquals(101,RecordingStore(context).points(s.id).size);assertNull(RecordingStore(context).unfinished());assertTrue(a.distanceMetres()>300)}
 fun testInterruptedStageCanRecoverWithoutInventingDowntime(){val s=trace();RecordingStore(context).recoverable();val recovered=RecordingStore(context).unfinished()!!;assertEquals("RECOVERABLE",recovered.state);assertEquals(s.last,recovered.last);RecordingStore(context).finish(recovered,null);assertEquals(100000L,FeatureStore(context).activities().first().elapsedTime().toMillis())}
 fun testFailedFinalizationRetainsStaging(){val store=RecordingStore(context);store.start("empty",Instant.now(),0);try{store.finish(store.unfinished()!!,null);fail("No samples should fail")}catch(_:IllegalArgumentException){};assertNotNull(store.unfinished())}
 fun testGpxRoundTripAndDuplicateImport(){val s=trace();RecordingStore(context).finish(s,100000);val output=ByteArrayOutputStream();GpxFiles(context).exportTo(s.id,output);val parsed=GpxFiles.parse(ByteArrayInputStream(output.toByteArray()));assertEquals(101,parsed.size);val first=GpxFiles(context).importFrom(ByteArrayInputStream(output.toByteArray()));val second=GpxFiles(context).importFrom(ByteArrayInputStream(output.toByteArray()));assertEquals(first,second);assertEquals(1,FeatureStore(context).activities().size)}
 fun testMalformedGpxCannotInsertActivity(){try{GpxFiles(context).importFrom(ByteArrayInputStream("<gpx><trk><trkseg><trkpt lat='0' lon='0'/></trkseg></trk></gpx>".toByteArray()));fail("Missing time")}catch(_:Exception){};assertTrue(FeatureStore(context).activities().isEmpty())}
 fun testGpxDoctypeRejected(){try{GpxFiles.parse(ByteArrayInputStream("<!DOCTYPE gpx [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><gpx>&x;</gpx>".toByteArray()));fail("Entity must reject")}catch(_:Exception){};assertTrue(FeatureStore(context).activities().isEmpty())}
 fun testRawArchiveRoundTripAndRepeatMerge(){val s=trace();val id=RecordingStore(context).finish(s,100000);val output=ByteArrayOutputStream();RecordingArchive(context).exportTo(output);FeatureStore(context).deleteActivity(id);assertTrue(RecordingStore(context).points(s.id).isEmpty());RecordingArchive(context).restoreFrom(ByteArrayInputStream(output.toByteArray()));RecordingArchive(context).restoreFrom(ByteArrayInputStream(output.toByteArray()));assertEquals(101,RecordingStore(context).points(s.id).size);assertEquals(1,FeatureStore(context).activities().size)}
 fun testBadArchiveRetainsExistingData(){trace();try{RecordingArchive(context).restoreFrom(ByteArrayInputStream(byteArrayOf(1,2,3)));fail("Bad archive")}catch(_:Exception){};assertEquals(101,RecordingStore(context).points("native").size)}
 fun testArchiveChecksumMismatchRollsBack(){val session=trace();RecordingStore(context).finish(session,100000);val original=ByteArrayOutputStream();RecordingArchive(context).exportTo(original);val changed=ByteArrayOutputStream();val source=java.util.zip.ZipInputStream(ByteArrayInputStream(original.toByteArray()));val target=java.util.zip.ZipOutputStream(changed);while(true){val entry=source.nextEntry?:break;val bytes=source.readBytes();target.putNextEntry(java.util.zip.ZipEntry(entry.name));target.write(if(entry.name=="recordings.jsonl")bytes+"\n".toByteArray()else bytes);target.closeEntry()};target.finish();try{RecordingArchive(context).restoreFrom(ByteArrayInputStream(changed.toByteArray()));fail("Checksum mismatch")}catch(_:Exception){};assertEquals(101,RecordingStore(context).points(session.id).size);assertEquals(1,FeatureStore(context).activities().size)}
 fun testOldBackupCannotEraseNativeRecording(){val features=FeatureStore(context);val old=features.exportUserData();val session=trace();RecordingStore(context).finish(session,100000);try{features.restoreUserData(old,false);fail("Owned recording must not be removed")}catch(_:IllegalArgumentException){};assertEquals(1,features.activities().size);assertEquals(101,RecordingStore(context).points(session.id).size)}
 fun testOptionalHealthCacheDoesNotSumMirroredSources(){val today=java.time.LocalDate.now();val at=today.atStartOfDay(java.time.ZoneOffset.UTC).toInstant();val m=org.racedaydreams.domain.health.HealthIntelligence.Metric.STEPS;val one=org.racedaydreams.domain.health.HealthIntelligence.Observation("a",m,today,at,at,1000.0,"one",at);val two=org.racedaydreams.domain.health.HealthIntelligence.Observation("b",m,today,at,at,1000.0,"two",at);val store=HealthIntelligenceStore(context);store.replace(setOf(m),today,today,listOf(one,two));val trend=org.racedaydreams.domain.health.HealthIntelligence.evaluate(store.recent(today),today).last();assertEquals(1000.0,trend.recent()!!,0.001);assertEquals(1,trend.recentDays());assertEquals("Insufficient evidence",trend.interpretation())}

 fun testV6UpgradeRetainsExistingActivityPlanStrengthWeightAndFeedbackPayloads(){
    val helper=ProfileDatabase.get(context);helper.close()
    val tables=listOf("user_profile","race_goal","activities","shoes","manual_results","coach_plan_versions","coach_current_plan","strength_exercises","strength_sessions","run_responses","run_feedback","coach_evidence","settings","planned_workouts")
    val before=linkedMapOf<String,List<String>>()
    context.openOrCreateDatabase(ProfileDatabase.NAME,0,null).use{db->
        db.execSQL("INSERT OR REPLACE INTO user_profile VALUES(1,0)")
        db.execSQL("INSERT OR REPLACE INTO race_goal VALUES(1,'TEN_K','Kept race','2027-03-01','FINISH',NULL)")
        db.execSQL("INSERT INTO activities VALUES('kept-run','health-connect','kept-source','source',1,2,'retained activity')")
        db.execSQL("INSERT INTO shoes VALUES('kept-shoe','retained shoe',0)")
        db.execSQL("INSERT INTO manual_results VALUES('kept-result',NULL,'5K',5000,'2026-10-22','retained result')")
        db.execSQL("INSERT INTO coach_plan_versions VALUES('kept-version','kept-plan',1,'retained plan')")
        db.execSQL("INSERT OR REPLACE INTO coach_current_plan VALUES(1,'kept-version')")
        db.execSQL("INSERT INTO strength_exercises VALUES('kept-lift','retained exercise')")
        db.execSQL("INSERT INTO strength_sessions VALUES('kept-strength','2026-10-22T00:00:00Z','retained sets')")
        db.execSQL("INSERT INTO run_responses VALUES('kept-run',NULL,'kept-version','retained response')")
        db.execSQL("INSERT INTO run_feedback VALUES('kept-run','kept-version','retained feedback')")
        db.execSQL("INSERT INTO coach_evidence VALUES('WEIGHT','kept-weight','retained weight'),('WEEKLY_REVIEW','kept-review','retained review')")
        db.execSQL("INSERT OR REPLACE INTO settings VALUES('reminders','retained preferences')")
        db.execSQL("INSERT INTO planned_workouts VALUES('kept-workout','2026-10-23',1,'retained prescription')")
        for(t in tables){val rows=mutableListOf<String>();db.rawQuery("SELECT * FROM $t ORDER BY 1",null).use{c->while(c.moveToNext())rows.add((0 until c.columnCount).joinToString("|"){i->if(c.isNull(i))"<null>"else c.getString(i)})};before[t]=rows}
        for(t in listOf("coach_support","recording_points","recording_events","recording_sessions","health_observations"))db.execSQL("DROP TABLE $t");db.version=6
    }
    val upgraded=helper.writableDatabase;assertEquals(8,upgraded.version)
    for(t in tables){val rows=mutableListOf<String>();upgraded.rawQuery("SELECT * FROM $t ORDER BY 1",null).use{c->while(c.moveToNext())rows.add((0 until c.columnCount).joinToString("|"){i->if(c.isNull(i))"<null>"else c.getString(i)})};assertEquals(t,before[t],rows)}
 }

 fun testExternalGpxDoesNotInventMovingTimeOrAccuracy(){val xml="<gpx version='1.1'><trk><trkseg><trkpt lat='0' lon='0'><time>2026-10-01T00:00:00Z</time></trkpt><trkpt lat='0' lon='0.00003'><time>2026-10-01T00:00:01Z</time></trkpt><trkpt lat='0' lon='0.00006'><time>2026-10-01T00:00:02Z</time></trkpt></trkseg></trk></gpx>";val id=GpxFiles(context).importFrom(ByteArrayInputStream(xml.toByteArray()));val activity=FeatureStore(context).activities().first{it.id()==id};assertEquals("gpx",activity.source().provider());assertNull(activity.movingTime());assertTrue(RecordingStore(context).points(activity.source().recordId()).all{it.fix().accuracy()==null});assertNull(activity.averageHeartRate())}

 fun testCompactCoreBackupAndRawArchiveRestoreDetailedEvidence(){val s=trace();val store=FeatureStore(context);val id=RecordingStore(context).finish(s,100000);val core=store.exportUserData();assertEquals(0,core.getJSONArray("activities").getJSONObject(0).getJSONArray("samples").length());store.restoreUserData(core,false);assertEquals(101,store.activities().first().samples().size);val raw=ByteArrayOutputStream();RecordingArchive(context).exportTo(raw);store.deleteActivity(id);store.restoreUserData(core,false);assertTrue(store.activities().first().samples().isEmpty());RecordingArchive(context).restoreFrom(ByteArrayInputStream(raw.toByteArray()));assertEquals(101,store.activities().first().samples().size)}

 fun testRecoveryActiveTimeUsesPauseEventsRatherThanLastGpsTime(){val store=RecordingStore(context);val wall=Instant.parse("2026-10-22T00:00:00Z");val e=RunMetricsEngine(0,wall);e.accept(RunMetricsEngine.Fix(wall,0,0.0,0.0,3.0,null,null,3.0));e.accept(RunMetricsEngine.Fix(wall.plusSeconds(1),1000,0.0,0.00003,3.0,null,null,3.0));e.pause(2000,wall.plusSeconds(2));e.resume(62000,wall.plusSeconds(62));e.accept(RunMetricsEngine.Fix(wall.plusSeconds(63),63000,0.0,0.00006,3.0,null,null,3.0));store.start("pause-recovery",wall,0);store.flush("pause-recovery",e.points(),e.events(),0,0,65000,"ACTIVE");store.finish(store.unfinished()!!,null);val a=FeatureStore(context).activities().first();assertEquals(65000L,a.elapsedTime().toMillis());assertEquals(5000L,a.movingTime()!!.toMillis())}
 fun testNormalEscapedGpxMetadataIsAccepted(){val xml="<gpx><metadata><name>Morning &amp; easy</name></metadata><trk><trkseg><trkpt lat='0' lon='0'><time>2026-10-01T00:00:00Z</time></trkpt><trkpt lat='0' lon='0.00003'><time>2026-10-01T00:00:01Z</time></trkpt></trkseg></trk></gpx>";assertEquals(2,GpxFiles.parse(ByteArrayInputStream(xml.toByteArray())).size)}
 fun testSeparateGpxTracksAreNotSilentlyOneActivity(){val xml="<gpx><trk/><trk/></gpx>";try{GpxFiles(context).importFrom(ByteArrayInputStream(xml.toByteArray()));fail("Multiple tracks")}catch(_:Exception){};assertTrue(FeatureStore(context).activities().isEmpty());assertNull(RecordingStore(context).unfinished())}

 fun testFourHourTraceUsesNormalizedRowsAndStillProvidesSplits(){val wall=Instant.parse("2026-10-22T00:00:00Z");val e=RunMetricsEngine(0,wall);for(i in 0..14400)e.accept(RunMetricsEngine.Fix(wall.plusSeconds(i.toLong()),i*1000L,0.0,i*0.000027,3.0,null,null,3.0));val store=RecordingStore(context);store.start("four-hours",wall,0);store.flush("four-hours",e.points(),e.events(),0,0,14400000,"ACTIVE");store.finish(store.unfinished()!!,14400000);ProfileDatabase.get(context).readableDatabase.rawQuery("SELECT length(payload) FROM activities WHERE id='rdd:four-hours'",null).use{c->assertTrue(c.moveToFirst());assertTrue(c.getLong(0)<16000)};val activity=FeatureStore(context).activities().first{it.id()=="rdd:four-hours"};assertEquals(14401,activity.samples().size);assertEquals(14400000L,activity.elapsedTime().toMillis());assertTrue(org.racedaydreams.domain.activity.SplitCalculator.calculate(activity,1000.0).splits().size>=42);assertTrue(FeatureStore(context).exportUserData().toString().length<100000)}

 fun testUnsupportedArchiveVersionsLeaveEvidenceIntact(){val session=trace();RecordingStore(context).finish(session,100000);val raw=ByteArrayOutputStream();RecordingArchive(context).exportTo(raw);for(version in listOf<Any>(3,1.5,"1")){val changed=ByteArrayOutputStream();val target=java.util.zip.ZipOutputStream(changed);java.util.zip.ZipInputStream(ByteArrayInputStream(raw.toByteArray())).use{source->while(true){val entry=source.nextEntry?:break;val bytes=source.readBytes();target.putNextEntry(java.util.zip.ZipEntry(entry.name));target.write(if(entry.name=="manifest.json")org.json.JSONObject(String(bytes,Charsets.UTF_8)).put("version",version).toString().toByteArray()else bytes);target.closeEntry()}};target.finish();try{RecordingArchive(context).restoreFrom(ByteArrayInputStream(changed.toByteArray()));fail("Unsupported version $version")}catch(_:Exception){};assertEquals(101,RecordingStore(context).points(session.id).size)}}

}
